// Persian (fa) translations for auto-generated catalog agent content.
//
// The catalog is generated from an English-only markdown corpus (see
// scripts/generate-catalog.mjs), so localized copy lives here, keyed by agent
// id. The i18n helpers in src/lib/i18n.tsx read this map; an agent missing from
// it falls back to the English catalog text, which keeps every card distinct
// instead of collapsing several agents into one generic division-level title.
//
// Coverage: every agent in src/data/catalog.generated.ts has an entry here, and
// `features` mirrors the catalog's feature count one-for-one. Re-running
// `bun run catalog` with new agents is what breaks that invariant, so add the
// new ids here at the same time.
//
// `prompts` only needs entries when the generated catalog carries non-Persian
// prompt strings; the default "برای شروع یک درخواست بنویس" is already Persian.

export type FaAgent = {
  name: string;
  description: string;
  longDescription: string;
  features: string[];
  prompts?: string[];
};

